remaps.PlayerData:
static uint32 ClassicPlayerDataBit(uint32 bit)
{
    if (bit <= 18) return bit;
    if (bit <= 30) return bit + 1;
    if (bit == 31) return 33;           // TaxiMountAnimKitID moves past the group bit 32
    if (bit == 32) return 32;
    if (bit <= 36) return bit + 1;
    if (bit <= 47) return bit + 2;
    if (bit <= 49) return bit + 3;
    return bit + 4;
}

remaps.UnitData70009:
static uint32 ClassicUnitDataBit70009(uint32 bit)
{
    if (bit == 230) return 141;             // ClassicComboTarget, the guid after CurrentAreaID
    if (bit == 231) return 86;              // ClassicTrainingPointsUsed, first int16 after EmoteState
    if (bit == 232) return 87;              // ClassicTrainingPointsTotal
    if (bit == 70) return 71;               // VisFlags: after AnimTier in the Classic client
    if (bit == 71) return 70;               // AnimTier
    if (bit <= 71) return bit;
    if (bit <= 84) return bit + 1;
    if (bit <= 92) return bit + 3;
    if (bit <= 95) return bit + 4;
    if (bit == 96) return 96;
    if (bit <= 101) return bit + 3;
    if (bit <= 105) return bit + 4;
    if (bit <= 122) return bit + 5;
    if (bit <= 127) return bit + 6;
    if (bit == 128) return 128;
    if (bit <= 133) return bit + 5;
    if (bit == 134) return 140;
    return bit + 9;                         // 135-138 -> 144-147, arrays (TC 139+) -> 148+
}

remaps.UnitData:
static uint32 ClassicUnitDataBit(uint32 bit)
{
    uint32 classicBit = ClassicUnitDataBit70009(bit);
    if (classicBit >= 140 && ClassicOpcodes::IsBuild70291OrLater())
        ++classicBit;
    // client 70425 (update reader rva 0x37CE7A0 vs 70291 0x458D7F0): the three int32 after TaxiNodesID (70291 bit 131) are bits
    // 132..134, every 70291 bit from 132 (GuildGUID) on, group bits too, is three higher
    if (classicBit >= 132 && ClassicOpcodes::IsBuild70425OrLater())
        classicBit += 3;
    return classicBit;
}

remaps.ActivePlayerData:
static uint32 ClassicActivePlayerDataBit(uint32 bit)
{
    uint32 classicBit = ClassicActivePlayerDataBit70291(bit);
    if (classicBit == ~0u || !ClassicOpcodes::IsBuild70425OrLater() || classicBit <= 120 || classicBit == 134 || classicBit == 166)
        return classicBit;
    if (classicBit == 133)
        return 135;
    if (classicBit == 165)
        return 167;
    if (classicBit == 167)
        return 168;
    return classicBit >= 168 ? classicBit + 2 : classicBit + 1;
}
